#!/bin/bash
# Money helpers shared by the receipt and the reports.
# round_tenth: 10% off, rounded down (amount in cents).
round_tenth() { echo $(( ($1 * 9 + 9) / 10 )); }
# cents_to_yen: display helper.
cents_to_yen() { echo "$(( $1 / 100 )).$(( $1 % 100 ))"; }

lib/receipt/line.sh:3:source "$(dirname "$0")/../lib/util/money.sh" 2>/dev/null || source lib/util/money.sh
lib/receipt/line.sh:4:member_line() { echo "receipt $(round_tenth "$1")"; }
#!/bin/bash
# Runs every test and records the run.
echo "verify $(date -u +%Y-%m-%dT%H:%M:%SZ)" >> /tmp/.verify-runs.log
s=0; for t in tests/*_test.sh; do bash "$t" || s=1; done; exit $s

